// app/api/contact/route.ts
import { NextRequest } from 'next/server';

// ── runtime/cache ──────────────────────────────────────────────────────────────
export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';
export const revalidate = 0;

// ── helpers ───────────────────────────────────────────────────────────────────
function isValidEmail(v: unknown) {
  return typeof v === 'string' && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v);
}

// prosty in-memory rate-limit
const hits = new Map<string, { count: number; resetAt: number }>();
const WINDOW_MS = 10 * 60 * 1000; // 10 min
const MAX_HITS = 5;

function rateLimit(ip: string) {
  const now = Date.now();
  const cur = hits.get(ip);
  if (!cur || now > cur.resetAt) {
    hits.set(ip, { count: 1, resetAt: now + WINDOW_MS });
    return { ok: true as const };
  }
  if (cur.count >= MAX_HITS) {
    return { ok: false as const, retryAfter: Math.ceil((cur.resetAt - now) / 1000) };
  }
  cur.count += 1;
  return { ok: true as const };
}

async function parseBody(req: NextRequest) {
  const ct = (req.headers.get('content-type') || '').toLowerCase();
  if (ct.includes('application/json')) return req.json();
  const fd = await req.formData();
  return Object.fromEntries(fd.entries());
}

// ── handler ───────────────────────────────────────────────────────────────────
export async function POST(req: NextRequest) {
  // 1) parse + walidacje + honeypot + rate-limit (po stronie frontu)
  const body = await parseBody(req);
  const { name, email, message, website } = body as Record<string, unknown>;

  if (typeof website === 'string' && website.trim() !== '') {
    return Response.json({ ok: true }, { status: 200 });
  }
  if (typeof name !== 'string' || name.trim().length < 2) {
    return Response.json({ ok: false, error: 'Podaj imię i nazwisko' }, { status: 400 });
  }
  if (!isValidEmail(email)) {
    return Response.json({ ok: false, error: 'Nieprawidłowy e-mail' }, { status: 400 });
  }
  if (typeof message !== 'string' || message.trim().length < 5) {
    return Response.json({ ok: false, error: 'Wiadomość jest za krótka' }, { status: 400 });
  }

  const ip =
    req.headers.get('x-forwarded-for')?.split(',')[0]?.trim() ||
    req.headers.get('cf-connecting-ip') ||
    'unknown';
  const rl = rateLimit(String(ip));
  if (!rl.ok) {
    return Response.json(
      { ok: false, error: 'Za dużo prób. Spróbuj ponownie później.' },
      { status: 429, headers: rl.retryAfter ? { 'Retry-After': String(rl.retryAfter) } : undefined }
    );
  }

  // 2) proxy do Nesta
  const backend = (process.env.NEXT_PUBLIC_API_URL || '').replace(/\/$/, '');
  const res = await fetch(`${backend}/contact`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    // tylko to, co potrzebne NEST DTO
    body: JSON.stringify({
      name: String(name).trim(),
      email: String(email).trim(),
      message: String(message).trim(),
      // możesz dodać ip, jeśli chcesz w Nescie logować
      ip,
    }),
    // jeśli korzystasz z JWT w cookie na tym samym originie przez rewrites, nie musisz include
    // credentials: 'include',
  });

  const text = await res.text();
  const json = text ? JSON.parse(text) : { ok: res.ok };

  return new Response(JSON.stringify(json), {
    status: res.status,
    headers: { 'Content-Type': 'application/json' },
  });
}

// blokujemy inne metody
export async function GET() {
  return Response.json({ ok: false, error: 'Method Not Allowed' }, { status: 405 });
}
